[patterns/application/api-microservices/PTN-APP-API-032-third-party-integration-pattern.md#step-4-create-base-adapter-framework]

##### Step 4: Create Base Adapter Framework

Establish reusable base adapter class providing common resilience, security, and observability functionality.

**Base Adapter Interface** (`IThirdPartyAdapter.cs`):

```csharp
namespace Gainwell.Integration.Adapters;

/// <summary>
/// Base interface for all third-party API adapters providing common functionality.
/// </summary>
public interface IThirdPartyAdapter
{
    /// <summary>
    /// Vendor name for metrics and logging (e.g., "fdb", "caqh", "ncpdp").
    /// </summary>
    string VendorName { get; }

    /// <summary>
    /// Health check status indicating circuit breaker state and last success.
    /// </summary>
    Task<HealthCheckResult> CheckHealthAsync(CancellationToken cancellationToken = default);
}
```

**Base Adapter Implementation** (`ThirdPartyAdapterBase.cs`):

```csharp
using Microsoft.Extensions.Logging;
using Polly;
using Polly.CircuitBreaker;
using Polly.Retry;
using Polly.Timeout;
using Polly.Wrap;
using System.Diagnostics;
using System.Net;
using Prometheus;

namespace Gainwell.Integration.Adapters;

/// <summary>
/// Base class for third-party API adapters providing resilience, security, and observability.
/// </summary>
public abstract class ThirdPartyAdapterBase : IThirdPartyAdapter
{
    protected readonly HttpClient _httpClient;
    protected readonly ILogger _logger;
    protected readonly IAsyncPolicy<HttpResponseMessage> _resiliencePolicy;

    // Prometheus metrics
    private static readonly Counter RequestCounter = Metrics.CreateCounter(
        "thirdparty_api_requests_total",
        "Total third-party API requests",
        new CounterConfiguration { LabelNames = new[] { "vendor", "operation", "status" } });

    private static readonly Histogram DurationHistogram = Metrics.CreateHistogram(
        "thirdparty_api_duration_seconds",
        "Third-party API request duration",
        new HistogramConfiguration { LabelNames = new[] { "vendor", "operation" } });

    private static readonly Gauge CircuitBreakerState = Metrics.CreateGauge(
        "thirdparty_api_circuit_breaker_state",
        "Circuit breaker state (0=closed, 1=open, 2=half-open)",
        new GaugeConfiguration { LabelNames = new[] { "vendor" } });

    public abstract string VendorName { get; }

    protected ThirdPartyAdapterBase(
        HttpClient httpClient,
        ILogger logger,
        CircuitBreakerConfig circuitBreakerConfig = null,
        RetryConfig retryConfig = null,
        TimeoutConfig timeoutConfig = null)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));

        // Build resilience policy combining circuit breaker, retry, and timeout
        _resiliencePolicy = BuildResiliencePolicy(
            circuitBreakerConfig ?? CircuitBreakerConfig.Default,
            retryConfig ?? RetryConfig.Default,
            timeoutConfig ?? TimeoutConfig.Default);
    }

    /// <summary>
    /// Executes HTTP request through resilience policy with observability.
    /// </summary>
    protected async Task<HttpResponseMessage> ExecuteRequestAsync(
        string operation,
        Func<Task<HttpResponseMessage>> requestFunc,
        CancellationToken cancellationToken = default)
    {
        // Start OpenTelemetry span
        using var activity = Activity.Current?.Source.StartActivity(
            $"{VendorName}-{operation}",
            ActivityKind.Client);

        activity?.SetTag("vendor.name", VendorName);
        activity?.SetTag("operation", operation);

        // Track request duration
        using var durationTimer = DurationHistogram
            .WithLabels(VendorName, operation)
            .NewTimer();

        try
        {
            var response = await _resiliencePolicy.ExecuteAsync(
                async ct => await requestFunc(),
                cancellationToken);

            // Record success metrics
            RequestCounter.WithLabels(VendorName, operation, "success").Inc();
            activity?.SetTag("http.status_code", (int)response.StatusCode);

            _logger.LogInformation(
                "Third-party API call succeeded: {Vendor} {Operation} {StatusCode} {Duration}ms",
                VendorName, operation, response.StatusCode, durationTimer.ObserveDuration().TotalMilliseconds);

            return response;
        }
        catch (BrokenCircuitException ex)
        {
            // Circuit breaker open - fail fast
            RequestCounter.WithLabels(VendorName, operation, "circuit_open").Inc();
            activity?.SetStatus(ActivityStatusCode.Error, "Circuit breaker open");

            _logger.LogWarning(ex,
                "Third-party API circuit breaker open: {Vendor} {Operation}",
                VendorName, operation);

            throw new ThirdPartyApiException(
                $"{VendorName} API temporarily unavailable (circuit breaker open)",
                VendorName,
                operation,
                ex);
        }
        catch (TimeoutRejectedException ex)
        {
            // Request timeout
            RequestCounter.WithLabels(VendorName, operation, "timeout").Inc();
            activity?.SetStatus(ActivityStatusCode.Error, "Timeout");

            _logger.LogError(ex,
                "Third-party API timeout: {Vendor} {Operation}",
                VendorName, operation);

            throw new ThirdPartyApiException(
                $"{VendorName} API timeout",
                VendorName,
                operation,
                ex);
        }
        catch (HttpRequestException ex)
        {
            // Network or HTTP error
            RequestCounter.WithLabels(VendorName, operation, "error").Inc();
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);

            _logger.LogError(ex,
                "Third-party API error: {Vendor} {Operation} {Message}",
                VendorName, operation, ex.Message);

            throw new ThirdPartyApiException(
                $"{VendorName} API error: {ex.Message}",
                VendorName,
                operation,
                ex);
        }
    }

    /// <summary>
    /// Builds Polly resilience policy combining circuit breaker, retry, and timeout.
    /// </summary>
    private IAsyncPolicy<HttpResponseMessage> BuildResiliencePolicy(
        CircuitBreakerConfig cbConfig,
        RetryConfig retryConfig,
        TimeoutConfig timeoutConfig)
    {
        // Circuit breaker policy
        var circuitBreakerPolicy = Policy
            .HandleResult<HttpResponseMessage>(r =>
                r.StatusCode >= HttpStatusCode.InternalServerError || // 5xx errors
                r.StatusCode == HttpStatusCode.RequestTimeout) // 408
            .CircuitBreakerAsync(
                cbConfig.ConsecutiveFailureThreshold,
                cbConfig.OpenDuration,
                onBreak: (result, duration) =>
                {
                    CircuitBreakerState.WithLabels(VendorName).Set(1); // OPEN
                    _logger.LogError(
                        "Circuit breaker opened for {Vendor} after {FailureCount} failures, duration {Duration}s",
                        VendorName, cbConfig.ConsecutiveFailureThreshold, duration.TotalSeconds);
                },
                onReset: () =>
                {
                    CircuitBreakerState.WithLabels(VendorName).Set(0); // CLOSED
                    _logger.LogInformation(
                        "Circuit breaker closed for {Vendor}, resuming normal operations",
                        VendorName);
                },
                onHalfOpen: () =>
                {
                    CircuitBreakerState.WithLabels(VendorName).Set(2); // HALF-OPEN
                    _logger.LogInformation(
                        "Circuit breaker half-open for {Vendor}, testing recovery",
                        VendorName);
                });

        // Retry policy with exponential backoff
        var retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r =>
                r.StatusCode == HttpStatusCode.TooManyRequests || // 429
                r.StatusCode == HttpStatusCode.ServiceUnavailable || // 503
                r.StatusCode >= HttpStatusCode.InternalServerError) // 5xx
            .WaitAndRetryAsync(
                retryConfig.MaxAttempts,
                retryAttempt => TimeSpan.FromMilliseconds(
                    retryConfig.InitialBackoffMs * Math.Pow(retryConfig.BackoffMultiplier, retryAttempt - 1)),
                onRetry: (result, timespan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Retrying {Vendor} request (attempt {RetryCount}/{MaxAttempts}) after {Delay}ms, status: {StatusCode}",
                        VendorName, retryCount, retryConfig.MaxAttempts, timespan.TotalMilliseconds, result.Result.StatusCode);
                });

        // Timeout policy
        var timeoutPolicy = Policy.TimeoutAsync<HttpResponseMessage>(
            timeoutConfig.TimeoutDuration,
            TimeoutStrategy.Pessimistic);

        // Combine policies: timeout -> retry -> circuit breaker (innermost to outermost)
        return Policy.WrapAsync(circuitBreakerPolicy, retryPolicy, timeoutPolicy);
    }

    public virtual async Task<HealthCheckResult> CheckHealthAsync(CancellationToken cancellationToken = default)
    {
        // Health check returns circuit breaker state and last success time
        var circuitBreakerState = CircuitBreakerState.WithLabels(VendorName).Value;

        return circuitBreakerState switch
        {
            0 => HealthCheckResult.Healthy($"{VendorName} circuit closed"),
            1 => HealthCheckResult.Unhealthy($"{VendorName} circuit open"),
            2 => HealthCheckResult.Degraded($"{VendorName} circuit half-open"),
            _ => HealthCheckResult.Degraded($"{VendorName} unknown state")
        };
    }
}

/// <summary>
/// Circuit breaker configuration.
/// </summary>
public record CircuitBreakerConfig(
    int ConsecutiveFailureThreshold,
    TimeSpan OpenDuration)
{
    public static CircuitBreakerConfig Default => new(5, TimeSpan.FromSeconds(60));
}

/// <summary>
/// Retry configuration with exponential backoff.
/// </summary>
public record RetryConfig(
    int MaxAttempts,
    int InitialBackoffMs,
    double BackoffMultiplier)
{
    public static RetryConfig Default => new(3, 100, 10); // 100ms, 1s, 10s
}

/// <summary>
/// Timeout configuration.
/// </summary>
public record TimeoutConfig(TimeSpan TimeoutDuration)
{
    public static TimeoutConfig Default => new(TimeSpan.FromSeconds(30));
}

/// <summary>
/// Custom exception for third-party API failures.
/// </summary>
public class ThirdPartyApiException : Exception
{
    public string VendorName { get; }
    public string Operation { get; }

    public ThirdPartyApiException(string message, string vendorName, string operation, Exception innerException = null)
        : base(message, innerException)
    {
        VendorName = vendorName;
        Operation = operation;
    }
}
```

