[patterns/application/api-microservices/PTN-APP-API-032-third-party-integration-pattern.md#step-6-implement-vendor-specific-adapter]

##### Step 6: Implement Vendor-Specific Adapter

Create concrete adapter implementation for specific third-party API vendor, inheriting from `ThirdPartyAdapterBase`.

**Example: First Databank Adapter** (`FirstDatabankAdapter.cs`):

```csharp
using Azure.Identity;
using Azure.Security.KeyVault.Secrets;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using System.Net.Http.Json;
using System.Text.Json;

namespace Gainwell.Pharmacy.Adapters;

/// <summary>
/// Adapter for First Databank (FDB) drug database API.
/// Implements anti-corruption layer translating between Gainwell domain and FDB API.
/// </summary>
public class FirstDatabankAdapter : ThirdPartyAdapterBase, IPharmacyDataProvider
{
    private readonly IMemoryCache _cache;
    private readonly SecretClient _secretClient;
    private string _cachedApiKey;
    private DateTime _apiKeyExpiry = DateTime.MinValue;

    public override string VendorName => "fdb";

    public FirstDatabankAdapter(
        HttpClient httpClient,
        ILogger<FirstDatabankAdapter> logger,
        IMemoryCache cache,
        SecretClient secretClient)
        : base(
            httpClient,
            logger,
            circuitBreakerConfig: new CircuitBreakerConfig(5, TimeSpan.FromSeconds(60)),
            retryConfig: new RetryConfig(3, 100, 10),
            timeoutConfig: new TimeoutConfig(TimeSpan.FromSeconds(10))) // Aggressive timeout for FDB
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _secretClient = secretClient ?? throw new ArgumentNullException(nameof(secretClient));

        // Configure HttpClient base address
        httpClient.BaseAddress = new Uri("https://api.fdb.com");
        httpClient.DefaultRequestHeaders.Add("Accept", "application/json");
    }

    public async Task<DrugInteractionResult> GetDrugInteractionsAsync(
        IEnumerable<string> drugCodes,
        CancellationToken cancellationToken = default)
    {
        var drugCodeList = drugCodes.ToList();

        // Check cache first (15-minute TTL)
        var cacheKey = $"fdb_interactions_{string.Join("_", drugCodeList.OrderBy(c => c))}";
        if (_cache.TryGetValue<DrugInteractionResult>(cacheKey, out var cachedResult))
        {
            _logger.LogInformation(
                "FDB drug interactions retrieved from cache: {DrugCount} drugs",
                drugCodeList.Count);
            return cachedResult;
        }

        // Build FDB API request
        var request = new HttpRequestMessage(HttpMethod.Post, "/v2/interactions")
        {
            Content = JsonContent.Create(new FdbInteractionRequest
            {
                DrugCodes = drugCodeList,
                IncludeSeverity = true,
                IncludeManagement = true
            })
        };

        // Add API key authentication
        request.Headers.Add("Authorization", $"Bearer {await GetApiKeyAsync(cancellationToken)}");

        // Execute through resilience policy
        var response = await ExecuteRequestAsync(
            "get_drug_interactions",
            async () => await _httpClient.SendAsync(request, cancellationToken),
            cancellationToken);

        response.EnsureSuccessStatusCode();

        // Deserialize FDB response
        var fdbResponse = await response.Content.ReadFromJsonAsync<FdbInteractionResponse>(cancellationToken);

        // Transform FDB model to Gainwell domain model
        var result = TransformToGainwellModel(fdbResponse);

        // Cache result for 15 minutes
        _cache.Set(cacheKey, result, TimeSpan.FromMinutes(15));

        return result;
    }

    public async Task<DrugPricingResult> GetDrugPricingAsync(
        string drugCode,
        decimal quantity,
        CancellationToken cancellationToken = default)
    {
        // Check cache (24-hour TTL for pricing data)
        var cacheKey = $"fdb_pricing_{drugCode}_{quantity}";
        if (_cache.TryGetValue<DrugPricingResult>(cacheKey, out var cachedResult))
        {
            return cachedResult;
        }

        // Build FDB API request
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"/v2/pricing?drugCode={Uri.EscapeDataString(drugCode)}&quantity={quantity}");
        request.Headers.Add("Authorization", $"Bearer {await GetApiKeyAsync(cancellationToken)}");

        // Execute through resilience policy
        var response = await ExecuteRequestAsync(
            "get_drug_pricing",
            async () => await _httpClient.SendAsync(request, cancellationToken),
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var fdbResponse = await response.Content.ReadFromJsonAsync<FdbPricingResponse>(cancellationToken);

        var result = new DrugPricingResult(
            DrugCode: drugCode,
            Quantity: quantity,
            Awp: fdbResponse.AverageWholesalePrice,
            Wac: fdbResponse.WholesaleAcquisitionCost,
            Mac: fdbResponse.MaximumAllowableCost,
            EffectiveDate: fdbResponse.PricingDate,
            RetrievedAt: DateTime.UtcNow);

        // Cache for 24 hours
        _cache.Set(cacheKey, result, TimeSpan.FromHours(24));

        return result;
    }

    /// <summary>
    /// Retrieves FDB API key from Azure Key Vault with 15-minute client-side caching.
    /// </summary>
    private async Task<string> GetApiKeyAsync(CancellationToken cancellationToken)
    {
        if (_cachedApiKey != null && DateTime.UtcNow < _apiKeyExpiry)
        {
            return _cachedApiKey;
        }

        var secret = await _secretClient.GetSecretAsync("fdb-api-key", cancellationToken: cancellationToken);
        _cachedApiKey = secret.Value.Value;
        _apiKeyExpiry = DateTime.UtcNow.AddMinutes(15);

        _logger.LogInformation("Retrieved FDB API key from Key Vault, cached until {Expiry}", _apiKeyExpiry);

        return _cachedApiKey;
    }

    /// <summary>
    /// Transforms FDB-specific response model to Gainwell domain model.
    /// Anti-corruption layer isolates internal code from FDB API changes.
    /// </summary>
    private DrugInteractionResult TransformToGainwellModel(FdbInteractionResponse fdbResponse)
    {
        var interactions = fdbResponse.Interactions.Select(fdb => new DrugInteraction(
            InteractionId: fdb.Id,
            Drug1Code: fdb.Drug1.Ndc,
            Drug1Name: fdb.Drug1.GenericName,
            Drug2Code: fdb.Drug2.Ndc,
            Drug2Name: fdb.Drug2.GenericName,
            Severity: MapSeverity(fdb.SeverityLevel),
            ClinicalSignificance: fdb.ClinicalEffect,
            ManagementRecommendation: fdb.ManagementStrategy
        )).ToList();

        return new DrugInteractionResult(interactions, DateTime.UtcNow);
    }

    /// <summary>
    /// Maps FDB severity codes to Gainwell domain enum.
    /// </summary>
    private InteractionSeverity MapSeverity(string fdbSeverity) => fdbSeverity?.ToUpper() switch
    {
        "1" or "MINOR" => InteractionSeverity.Minor,
        "2" or "MODERATE" => InteractionSeverity.Moderate,
        "3" or "MAJOR" => InteractionSeverity.Major,
        "4" or "CONTRAINDICATED" => InteractionSeverity.Contraindicated,
        _ => InteractionSeverity.Minor
    };
}

// FDB API-specific DTOs (not exposed outside adapter)
internal record FdbInteractionRequest
{
    public List<string> DrugCodes { get; init; }
    public bool IncludeSeverity { get; init; }
    public bool IncludeManagement { get; init; }
}

internal record FdbInteractionResponse
{
    public List<FdbInteraction> Interactions { get; init; }
}

internal record FdbInteraction
{
    public string Id { get; init; }
    public FdbDrug Drug1 { get; init; }
    public FdbDrug Drug2 { get; init; }
    public string SeverityLevel { get; init; }
    public string ClinicalEffect { get; init; }
    public string ManagementStrategy { get; init; }
}

internal record FdbDrug
{
    public string Ndc { get; init; }
    public string GenericName { get; init; }
}

internal record FdbPricingResponse
{
    public decimal AverageWholesalePrice { get; init; }
    public decimal WholesaleAcquisitionCost { get; init; }
    public decimal MaximumAllowableCost { get; init; }
    public DateTime PricingDate { get; init; }
}
```

