[patterns/application/api-microservices/PTN-APP-API-032-third-party-integration-pattern.md#step-7-register-adapter-in-dependency-injection]

##### Step 7: Register Adapter in Dependency Injection

Configure adapter in ASP.NET Core `Program.cs` with HttpClient factory, Azure Key Vault client, caching, and health checks.

```csharp
using Azure.Identity;
using Azure.Security.KeyVault.Secrets;
using Gainwell.Pharmacy.Adapters;
using Gainwell.Pharmacy.Contracts;
using Microsoft.Extensions.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);

// Azure Key Vault client with managed identity
builder.Services.AddSingleton(sp =>
{
    var keyVaultUri = new Uri(builder.Configuration["KeyVault:VaultUri"]);
    return new SecretClient(keyVaultUri, new DefaultAzureCredential());
});

// Memory cache for adapter response caching
builder.Services.AddMemoryCache();

// Register FDB adapter with typed HttpClient
builder.Services.AddHttpClient<IPharmacyDataProvider, FirstDatabankAdapter>()
    .ConfigureHttpClient(client =>
    {
        client.BaseAddress = new Uri("https://api.fdb.com");
        client.Timeout = TimeSpan.FromSeconds(30); // Overall HttpClient timeout (Polly timeout is 10s)
    });

// Health checks including adapter circuit breaker state
builder.Services.AddHealthChecks()
    .AddCheck<AdapterHealthCheck>("fdb-adapter");

var app = builder.Build();

// Expose Prometheus metrics endpoint
app.MapMetrics(); // Requires prometheus-net.AspNetCore

// Health check endpoint for Kubernetes probes
app.MapHealthChecks("/health");

app.Run();
```

**Adapter Health Check Implementation**:

```csharp
using Microsoft.Extensions.Diagnostics.HealthChecks;

public class AdapterHealthCheck : IHealthCheck
{
    private readonly IPharmacyDataProvider _adapter;

    public AdapterHealthCheck(IPharmacyDataProvider adapter)
    {
        _adapter = adapter;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        // Delegate to adapter health check (circuit breaker state)
        return await ((IThirdPartyAdapter)_adapter).CheckHealthAsync(cancellationToken);
    }
}
```

