##### Step 8: Unit Testing with Mock Adapter

Create unit tests for services using adapter, mocking adapter interface to avoid third-party API dependencies.

**Unit Test Example** (`PharmacyClaimServiceTests.cs`):

```csharp
using Gainwell.Pharmacy.Contracts;
using Gainwell.Pharmacy.Services;
using Moq;
using Xunit;

public class PharmacyClaimServiceTests
{
    [Fact]
    public async Task AdjudicateClaim_WithDrugInteraction_DeniesClaimAsync()
    {
        // Arrange
        var mockAdapter = new Mock<IPharmacyDataProvider>();
        mockAdapter
            .Setup(a => a.GetDrugInteractionsAsync(
                It.IsAny<IEnumerable<string>>(),
                It.IsAny<CancellationToken>()))
            .ReturnsAsync(new DrugInteractionResult(
                new[]
                {
                    new DrugInteraction(
                        "INT-001",
                        "00071-0156-23",
                        "Warfarin",
                        "00378-6205-10",
                        "Ibuprofen",
                        InteractionSeverity.Major,
                        "Increased bleeding risk",
                        "Use alternative analgesic")
                },
                DateTime.UtcNow));

        var service = new PharmacyClaimService(mockAdapter.Object);
        var claim = new PharmacyClaim
        {
            ClaimId = "CLM-12345",
            DrugCodes = new[] { "00071-0156-23", "00378-6205-10" }
        };

        // Act
        var result = await service.AdjudicateClaimAsync(claim);

        // Assert
        Assert.Equal(ClaimStatus.Denied, result.Status);
        Assert.Contains("Major drug interaction detected", result.DenialReason);
    }
}
```

