```csharp
public class PharmacyClaimService
{
    private readonly IPharmacyDataProvider _pharmacyData;

    public async Task<ClaimAdjudicationResult> AdjudicateClaimAsync(PharmacyClaim claim)
    {
        try
        {
            // Attempt drug interaction check through adapter
            var interactions = await _pharmacyData.GetDrugInteractionsAsync(claim.DrugCodes);

            if (interactions.Interactions.Any(i => i.Severity >= InteractionSeverity.Major))
            {
                return new ClaimAdjudicationResult
                {
                    Status = ClaimStatus.Denied,
                    DenialReason = "Major drug interaction detected",
                    Interactions = interactions.Interactions
                };
            }

            return new ClaimAdjudicationResult { Status = ClaimStatus.Approved };
        }
        catch (ThirdPartyApiException ex) when (ex.VendorName == "fdb")
        {
            _logger.LogWarning(ex, "FDB API unavailable, using cached data for claim {ClaimId}", claim.ClaimId);

            // Graceful degradation: Check local interaction database (updated daily from FDB)
            var cachedInteractions = await _localDatabase.GetDrugInteractionsAsync(claim.DrugCodes);

            if (cachedInteractions.Any(i => i.Severity >= InteractionSeverity.Major))
            {
                return new ClaimAdjudicationResult
                {
                    Status = ClaimStatus.PendingManualReview,
                    DenialReason = "Potential drug interaction (FDB unavailable, using cached data)",
                    RequiresPharmacistReview = true
                };
            }

            // Approve with warning flag for pharmacist awareness
            return new ClaimAdjudicationResult
            {
                Status = ClaimStatus.Approved,
                Warnings = new[] { "Drug interaction check used cached data (FDB temporarily unavailable)" }
            };
        }
    }
}
