// Failover coordinator with automatic vendor selection
public class FailoverProviderVerifier : IProviderVerifier
{
    private readonly IEnumerable<IProviderVerifier> _verifiers;
    private readonly ILogger _logger;

    public FailoverProviderVerifier(
        CaqhAdapter caqhAdapter,          // Primary
        NpdbAdapter npdbAdapter,          // Secondary
        StateLicensingAdapter stateAdapter, // Tertiary
        ILogger<FailoverProviderVerifier> logger)
    {
        _verifiers = new[] { caqhAdapter, npdbAdapter, stateAdapter };
        _logger = logger;
    }

    public async Task<ProviderCredentialStatus> VerifyCredentialsAsync(
        string npi,
        string licenseNumber,
        CancellationToken cancellationToken = default)
    {
        // Try each vendor in order until success
        foreach (var verifier in _verifiers)
        {
            try
            {
                var result = await verifier.VerifyCredentialsAsync(npi, licenseNumber, cancellationToken);

                if (verifier is CaqhAdapter)
                {
                    _logger.LogInformation("Credentials verified using primary vendor (CAQH) for NPI {Npi}", npi);
                }
                else
                {
                    _logger.LogWarning(
                        "Credentials verified using failover vendor ({Vendor}) for NPI {Npi}",
                        ((IThirdPartyAdapter)verifier).VendorName, npi);
                }

                return result;
            }
            catch (ThirdPartyApiException ex)
            {
                _logger.LogWarning(ex,
                    "Vendor {Vendor} unavailable, trying next failover vendor for NPI {Npi}",
                    ((IThirdPartyAdapter)verifier).VendorName, npi);

                // Continue to next vendor
                continue;
            }
        }

        // All vendors failed
        throw new AllVendorsUnavailableException(
            $"All credentialing vendors unavailable for NPI {npi}");
    }
}
